def followup_view(inputs, prior):
    packet=inputs.get('tenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('tenth period packet changed')
    if prior is None or prior['counts']['after']!=82 or packet['prior_digest']!=digest(prior):raise ValueError('tenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('tenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=26 or len(packet['sources'])!=26 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('tenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('tenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('tenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('tenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('tenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('tenth period page changed')
    for row in FINANCIAL:
        yoy=((D(row['h1_yuan'])-D(row['prior_h1_yuan']))/abs(D(row['prior_h1_yuan']))*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('tenth period H1 arithmetic changed')
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('tenth period quarter bridge changed')
        if row['reported_quarter_yuan']is not None and D(row['quarter_yuan'])!=D(row['reported_quarter_yuan']):raise ValueError('tenth period reported quarter changed')
        for aid,page,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(page)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('tenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('tenth period windows changed')
    return {'through':'2026-11-19','title':'兑付、保证金和重组进展，究竟关闭了什么风险？','answer':'龙大转债已兑付，但形成新代偿债权，投资协议仍未替代法院受理；建艺报名保证金已缴，仍是庭外重组且经营承压；和科申请继续补材料，2026期间又亏损；萃华则从复牌警示走到正式退市，不能从样本中删掉。把履约、程序和经营分别更新，才能看清哪些旧待办可关闭、哪些仍要等。','chains':CHAINS,'financial_bridge':FINANCIAL,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':26,'new_files':23,'reused_files':3,'pages':sum(s['pages']for s in sources.values()),'new_pages':686,'viewed_pages':len(VISUAL),'initial_coverage':82,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'23份新原件686页、复用3份10页，视觉核23关键页，不称全文逐页审阅；212条期间目录不认证所有渠道穷尽。64个完整市场窗口与11个未满窗口，另18个股票窗口为空，不把完整市场日数当可算股票样本。期初覆盖仍82/150、缺68。建艺董事会日期差异未获更正，原文并列。3项单季现金为累计差额推算，期间财报不认证年度审计消除；萃华缺价与复权冲突保留。公告同窗不识别净因果，重复文件不增加经验验证。','method_promotions':0}
